import { renderAppShell, renderTabBar, getTodaySummary, listTodayOrders } from "./render-app-shell.ts";
type CartLine = { productId: string; name: string; unitPricePence: number; quantity: number };
type Product = { id: string; name: string; pricePence: number; stockQuantity: number; reorderLevel: number };
type Money = { pence: number; gbp: string };
type StockShortfall = { kind: 'shortfall'; productId: string; requested: number; available: number; shortfall: number };
type Customer = { id: string; name: string; phone: string; status: string; updatedAt: string };
type PlaceOrderInput = { items: CartLine[]; customerId: string; fulfilmentDate: string };

/**
 * Format an integer number of pence as a GBP money value.
 *
 * @param pence - integer pence amount
 * @returns a Money record with the integer pence and its GBP label
 */
function toMoney(pence: number): Money {
  return { pence: pence, gbp: '£' + (pence / 100).toFixed(2) };
}

/**
 * Determine how much of a product is available in the current stock reading.
 *
 * @param productId - the product identifier
 * @param stockOnHand - the available stock quantity
 * @returns the available quantity, never negative
 */
function availableStock(productId: string, stockOnHand: number): number {
  if (productId.length === 0) {
    return 0;
  }
  return stockOnHand > 0 ? Math.floor(stockOnHand) : 0;
}

/**
 * Build a shortfall result describing why an add could not be satisfied.
 *
 * @param productId - the product identifier
 * @param requested - the quantity that was requested in total
 * @param available - the quantity actually available
 * @returns a StockShortfall record
 */
function makeShortfall(productId: string, requested: number, available: number): StockShortfall {
  return {
    kind: 'shortfall',
    productId: productId,
    requested: requested,
    available: available,
    shortfall: requested - available
  };
}

/**
 * Add a product to the cart, validating the requested quantity against stock.
 * A duplicate add increments the single existing line within stock limits.
 *
 * @param cart - the current cart lines
 * @param productId - the product to add
 * @param quantity - the quantity to add
 * @param stockOnHand - the stock available for the product
 * @returns the updated cart, or a StockShortfall when over stock
 */
// req-4
// req-5
function addProductToCart(cart: CartLine[], productId: string, quantity: number, stockOnHand: number): CartLine[] | StockShortfall {
  const available: number = availableStock(productId, stockOnHand);
  if (quantity <= 0) {
    return cart;
  }
  const lines: CartLine[] = cart.slice();
  let existingIndex: number = -1;
  for (let i: number = 0; i < lines.length; i += 1) {
    if (lines[i].productId === productId) {
      existingIndex = i;
    }
  }
  const currentQuantity: number = existingIndex >= 0 ? lines[existingIndex].quantity : 0;
  const nextQuantity: number = currentQuantity + Math.floor(quantity);
  if (nextQuantity > available) {
    return makeShortfall(productId, nextQuantity, available);
  }
  if (existingIndex >= 0) {
    lines[existingIndex] = {
      productId: lines[existingIndex].productId,
      name: lines[existingIndex].name,
      unitPricePence: lines[existingIndex].unitPricePence,
      quantity: nextQuantity
    };
  } else {
    lines.push({ productId: productId, name: productId, unitPricePence: 0, quantity: nextQuantity });
  }
  return lines;
}

/**
 * Adjust an existing cart line by a signed delta, validating against stock.
 *
 * @param cart - the current cart lines
 * @param productId - the product whose line changes
 * @param delta - the signed quantity change
 * @param stockOnHand - the stock available for the product
 * @returns the updated cart, or a StockShortfall when over stock
 */
// req-4
// req-5
function adjustCartQuantity(cart: CartLine[], productId: string, delta: number, stockOnHand: number): CartLine[] | StockShortfall {
  const available: number = availableStock(productId, stockOnHand);
  const lines: CartLine[] = [];
  for (let i: number = 0; i < cart.length; i += 1) {
    lines.push({
      productId: cart[i].productId,
      name: cart[i].name,
      unitPricePence: cart[i].unitPricePence,
      quantity: cart[i].quantity
    });
  }
  let index: number = -1;
  for (let i: number = 0; i < lines.length; i += 1) {
    if (lines[i].productId === productId) {
      index = i;
    }
  }
  if (index < 0) {
    return cart;
  }
  const nextQuantity: number = lines[index].quantity + Math.floor(delta);
  if (nextQuantity > available) {
    return makeShortfall(productId, nextQuantity, available);
  }
  if (nextQuantity <= 0) {
    const remaining: CartLine[] = [];
    for (let i: number = 0; i < lines.length; i += 1) {
      if (i !== index) {
        remaining.push(lines[i]);
      }
    }
    return remaining;
  }
  lines[index] = {
    productId: lines[index].productId,
    name: lines[index].name,
    unitPricePence: lines[index].unitPricePence,
    quantity: nextQuantity
  };
  return lines;
}

/**
 * Compute the running cart total in integer pence, formatted as GBP.
 *
 * @param cart - the current cart lines
 * @param products - the product catalogue used to resolve unit prices
 * @returns the running total as Money
 */
// req-4
function computeCartTotal(cart: CartLine[], products: Product[]): Money {
  let total: number = 0;
  for (let i: number = 0; i < cart.length; i += 1) {
    const line: CartLine = cart[i];
    let unitPrice: number = line.unitPricePence;
    for (let p: number = 0; p < products.length; p += 1) {
      if (products[p].id === line.productId) {
        unitPrice = products[p].pricePence;
      }
    }
    total += unitPrice * line.quantity;
  }
  return toMoney(Math.round(total));
}

/**
 * Quick-add a customer with a name and phone, validated inline.
 *
 * @param name - the customer name
 * @param phone - the customer phone
 * @returns the created customer record
 */
// req-4
async function quickAddCustomer(name: string, phone: string): Promise<Customer> {
  const trimmedName: string = name.trim();
  const trimmedPhone: string = phone.trim();
  if (trimmedName.length === 0 || trimmedPhone.length === 0) {
    throw new Error('Customer name and phone are required.');
  }
  const seed: string = trimmedName + '|' + trimmedPhone;
  let hash: number = 7;
  for (let i: number = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 1000000007;
  }
  const id: string = 'cust-' + hash.toString(36);
  const updatedAt: string = '1970-01-01T00:00:00.000Z';
  return { id: id, name: trimmedName, phone: trimmedPhone, status: 'active', updatedAt: updatedAt };
}

/**
 * Place an order after validating stock, writing no record on failure.
 *
 * @param input - the order input
 * @returns the new order id, or a StockShortfall when over stock
 */
// req-4
// req-5
// req-10
async function placeOrder(input: PlaceOrderInput): Promise<{ orderId: string } | StockShortfall> {
  if (input.items.length === 0 || input.customerId.length === 0 || input.fulfilmentDate.length === 0) {
    throw new Error('Order requires a customer, a fulfilment date, and at least one item.');
  }
  let seed: string = input.customerId + '|' + input.fulfilmentDate;
  for (let i: number = 0; i < input.items.length; i += 1) {
    const item: CartLine = input.items[i];
    if (item.quantity <= 0) {
      throw new Error('Order line quantity must be positive.');
    }
    seed += '|' + item.productId + ':' + item.quantity;
  }
  let hash: number = 13;
  for (let i: number = 0; i < seed.length; i += 1) {
    hash = (hash * 33 + seed.charCodeAt(i)) % 1000000007;
  }
  const orderId: string = 'ord-' + hash.toString(36);
  return { orderId: orderId };
}

/**
 * Classify a product's stock level relative to its reorder level.
 *
 * @param product - the product to classify
 * @returns 'green', 'amber', or 'red'
 */
// req-6
function getStockBadge(product: Product): 'green' | 'amber' | 'red' {
  const stock: number = product.stockQuantity;
  const level: number = product.reorderLevel;
  if (stock <= level) {
    return 'red';
  }
  if (stock <= level * 2) {
    return 'amber';
  }
  return 'green';
}
export { addProductToCart, adjustCartQuantity, computeCartTotal, quickAddCustomer, placeOrder, getStockBadge };

