function revenuePenceFor(orders: Order[]): number {
  let total: number = 0;
  let i: number = 0;
  while (i < orders.length) {
    total = total + Math.trunc(orders[i].totalPence);
    i = i + 1;
  }
  return total;
}

/**
 * Counts the items sold across a set of orders.
 * @param orders orders to count
 * @returns item count
 */
function itemsSoldFor(orders: Order[]): number {
  let items: number = 0;
  let i: number = 0;
  while (i < orders.length) {
    const lines: OrderLine[] = Array.isArray(orders[i].lines) ? orders[i].lines : [];
    let j: number = 0;
    while (j < lines.length) {
      items = items + Math.trunc(lines[j].quantity);
      j = j + 1;
    }
    i = i + 1;
  }
