// req-3
async function listTodayOrders(snapshot: LocalSnapshot, day: string): Promise<Order[]> {
  const orders: Order[] = ordersForDay(snapshot, day);
  const sorted: Order[] = orders.slice();
  sorted.sort(function (a: Order, b: Order): number {
    if (a.createdAt < b.createdAt) {
      return 1;
    }
    if (a.createdAt > b.createdAt) {
      return -1;
    }
    if (a.id < b.id) {
      return 1;
    }
    if (a.id > b.id) {
      return -1;
    }
    return 0;
