  id: string;
  productId: string;
  kind: string;
  quantity: number;
  reason: string | null;
  updatedAt: string;
};

type AlertContract = {
  id: string;
  productId: string;
  productName: string;
  stockOnHand: number;
  reorderLevel: number;
  suggestedQuantity: number;
  recordedAt: string;
  status: string;
};

