type LowStockAlert = {
  id: string;
  productId: string;
  productName: string;
  stockOnHand: number;
  reorderLevel: number;
  suggestedQuantity: number;
  recordedAt: string;
};

/**
 * Deterministically derive a stable alert id from a product id.
 *
 * @param productId - the shared-contract product identifier
 * @returns a stable alert identifier string
 */
function deriveAlertId(productId: string): string {
  return 'alert-' + productId;
}

/**
 * Compute the suggested reorder quantity for a product: enough to restore
 * stock to twice its reorder level, never less than the shortfall.
 *
 * @param stockOnHand - current stock on hand for the product
 * @param reorderLevel - the product's reorder threshold
 * @returns the suggested reorder quantity, at least 1
 */
function computeSuggestedQuantity(stockOnHand: number, reorderLevel: number): number {
  const shortfall: number = reorderLevel - stockOnHand;
  const target: number = reorderLevel * 2 - stockOnHand;
  const basis: number = target > shortfall ? target : shortfall;
  if (!isFinite(basis) || basis <= 0) {
    return 1;
  }
