function buildLowStockAlert(product: ProductContract): LowStockAlert {
  return {
    id: deriveAlertId(product.id),
    productId: product.id,
    productName: product.name,
    stockOnHand: product.stockOnHand,
    reorderLevel: product.reorderLevel,
    suggestedQuantity: computeSuggestedQuantity(product.stockOnHand, product.reorderLevel),
    recordedAt: product.updatedAt,
  };
}

/**
 * Compare two alert records so that the newest recordedAt sorts first;
 * ties are broken deterministically by product id.
 *
 * @param a - left alert
 * @param b - right alert
