 */
function compareNewestFirst(a: LowStockAlert, b: LowStockAlert): number {
  const at: number = Date.parse(a.recordedAt);
  const bt: number = Date.parse(b.recordedAt);
  const av: number = isNaN(at) ? 0 : at;
  const bv: number = isNaN(bt) ? 0 : bt;
