    return -1;
  }
  if (a.productId > b.productId) {
    return 1;
  }
  return 0;
}

/**
 * List every product in the local snapshot whose stock on hand is at or
 * below its reorder level, as low-stock alerts ordered newest first. The
 * list is derived deterministically from the snapshot so repeated reads
 * agree with the back-office contracts.
 *
 * // req-7
 *
 * @param snapshot - the locally persisted snapshot of shared-contract records
 * @returns a promise resolving to the newest-first list of low-stock alerts
 */
async function listLowStockAlerts(snapshot: LocalSnapshot): Promise<LowStockAlert[]> {
  const products: ProductContract[] = snapshot && Array.isArray(snapshot.products) ? snapshot.products : [];
  const low: LowStockAlert[] = [];
  let index: number = 0;
  while (index < products.length) {
    const product: ProductContract = products[index];
    if (product && product.stockOnHand <= product.reorderLevel) {
      low.push(buildLowStockAlert(product));
    }
    index = index + 1;
  }
