  if (needle.length === 0) {
    return true;
  }
  return normalize(product.name).indexOf(needle) !== -1;
}

function cloneProduct(product: Product): Product {
  return {
    id: product.id,
    name: product.name,
    status: product.status,
    updatedAt: product.updatedAt,
    pricePence: product.pricePence,
    stockOnHand: product.stockOnHand,
    reorderLevel: product.reorderLevel
  };
}

/**
 * Search the locally persisted product snapshot by name.
 *
 * An empty (or whitespace-only) query returns the full, unfiltered product
 * list. A query with no matches returns an empty array — callers render a
 * clear, testable empty state from that result rather than a blank screen.
 * Results are returned in the snapshot's own order, and each returned product
 * is a fresh object so callers cannot mutate the persisted snapshot through
 * the result.
 *
 * // req-6
 * // req-8
 *
 * @param query - The raw search text; trimmed and matched case-insensitively.
 * @param snapshot - The local snapshot holding the shared-contract products.
 * @returns A promise resolving to the matched products (a copy of each).
 */
async function searchProducts(query: string, snapshot: LocalSnapshot): Promise<Product[]> {
  const needle: string = normalize(query);
  const source: Product[] = snapshot && Array.isArray(snapshot.products) ? snapshot.products : [];
  const out: Product[] = [];
  for (let i = 0; i < source.length; i += 1) {
