  const seed: string = name + '|' + phone;
  let acc = 0;
  for (let i = 0; i < seed.length; i += 1) {
    acc = (acc * 131 + seed.charCodeAt(i)) % 2147483647;
  }
  return 'customer-' + acc.toString(36);
