    return { id: "", status: "refused", updatedAt: "", name: "", phone: "" };
  }
  const customer: Customer = {
    id: deriveCustomerId(name, phone),
    status: "active",
    updatedAt: String(command.scheduledAt ?? ""),
    name,
    phone
