async function listShowRuns(id: string, limit?: number): Promise<ShowRun[]> {
  const target: string = String(id);
  const matched: ShowRun[] = [];
  for (let i = 0; i < SHOW_RUNS.length; i += 1) {
    if (SHOW_RUNS[i].showId === target) {
      matched.push(SHOW_RUNS[i]);
    }
  }
  matched.sort(function (a: ShowRun, b: ShowRun): number {
    if (a.createdAt === b.createdAt) {
      return a.id < b.id ? 1 : a.id > b.id ? -1 : 0;
    }
    return a.createdAt < b.createdAt ? 1 : -1;
