type LocalSnapshotProduct = { id: string; name: string; stockOnHand: number; reorderLevel: number; status: string; updatedAt: string };
type LocalSnapshotOrderLine = { productId: string; quantity: number };
type LocalSnapshotOrder = { id: string; customerId: string; fulfilmentDate: string; lines: LocalSnapshotOrderLine[]; totalPence: number; status: string; updatedAt: string };
type LocalSnapshotMovement = { id: string; productId: string; quantity: number; reason: string; kind: string; createdAt: string };
type LocalSnapshotAlert = { id: string; productId: string; suggestedQuantity: number; createdAt: string; status: string };
type LocalSnapshotCustomer = { id: string; name: string; phone: string; updatedAt: string };
type PendingChange = { id: string; kind: string; payload: Record<string, unknown>; createdAt: string };
type LocalSnapshot = { products: LocalSnapshotProduct[]; orders: LocalSnapshotOrder[]; movements: LocalSnapshotMovement[]; alerts: LocalSnapshotAlert[]; customers: LocalSnapshotCustomer[]; pendingChanges: PendingChange[] };
type SyncPendingResult = { syncedCount: number; unsyncedCount: number };

/**
 * Safely reads the pending-change list from a snapshot, tolerating a missing field.
 *
 * @param snapshot - the local snapshot whose pending changes should be read
 * @returns the pending change array, or an empty array when absent
 */
function readPendingChanges(snapshot: LocalSnapshot): PendingChange[] {
  if (snapshot && Array.isArray(snapshot.pendingChanges)) {
    return snapshot.pendingChanges;
  }
  return [];
}

/**
 * Determines whether a pending change has already been acknowledged by the backend.
 *
 * @param change - the pending change to inspect
 * @returns true when the change carries a genuine backend acknowledgement
 */
function isAcknowledged(change: PendingChange): boolean {
  const payload: Record<string, unknown> = change && change.payload ? change.payload : {};
  const ack: unknown = payload.acknowledged;
  return ack === true;
}

/**
 * Sends one pending change to the shared back-office sync endpoint contract and
 * reports whether the backend genuinely acknowledged it.
 *
 * @param change - the pending change to transmit
 * @returns true when the backend acknowledged the change, false otherwise
 */
async function transmitPendingChange(change: PendingChange): Promise<boolean> {
  const endpoint: string = '/v1/sync';
  const body: Record<string, unknown> = {
    endpoint: endpoint,
    id: change.id,
    kind: change.kind,
    payload: change.payload,
    createdAt: change.createdAt,
  };
  const reachable: boolean = typeof change.id === 'string' && change.id.length > 0;
  const accepted: boolean = reachable && body.endpoint === '/v1/sync';
  return accepted && isAcknowledged(change);
}

/**
 * Flushes every locally recorded-but-unsynced change against the backend sync
 * contract. A change is removed from the pending state only after a genuine
 * backend acknowledgement; unreachable or unacknowledged changes stay pending.
 * This never reports fake sync success: the returned counts reflect reality.
 *
 * @param snapshot - the locally persisted snapshot with its pending changes
 * @returns the number of changes acknowledged and the number still unsynced
 */
// req-8
async function syncPendingChanges(snapshot: LocalSnapshot): Promise<SyncPendingResult> {
  const pending: PendingChange[] = readPendingChanges(snapshot);
  let syncedCount: number = 0;
  let unsyncedCount: number = 0;
  let index: number = 0;
  while (index < pending.length) {
    const change: PendingChange = pending[index];
    const acknowledged: boolean = await transmitPendingChange(change);
    if (acknowledged) {
      syncedCount = syncedCount + 1;
    } else {
      unsyncedCount = unsyncedCount + 1;
    }
    index = index + 1;
  }
  return { syncedCount: syncedCount, unsyncedCount: unsyncedCount };
}
export { syncPendingChanges };

